VAR
    Overload_Timer : TON;
    Motor_Trip_Latched : BOOL;
END_VAR

// Motor Thermal Protection Logic
// Overload detection based on current and temperature thresholds
// Rated Current = 41.5A, Service Factor = 1.15 => Max Continuous Current = 47.7A
// Thermal limit assumed at 155C (Class F insulation)

// 1. Monitor for Overload Conditions
// Trip if current exceeds 115% of rated current for 3 seconds, or temperature exceeds 150C
Overload_Timer(IN := (Motor_Current > 47.7) OR (Motor_Winding_Temp > 150.0), PT := T#3S);

// 2. Latch the trip state
IF Overload_Timer.Q THEN
    Motor_Trip_Latched := TRUE;
END_IF;

// 3. Reset logic
IF Fault_Reset THEN
    Motor_Trip_Latched := FALSE;
END_IF;

// 4. Alarm signalling
Overload_Alarm := Motor_Trip_Latched OR (Motor_Winding_Temp > 140.0);

// 5. Shutdown logic
// Stop the motor if a trip is latched or if critical temperature is reached (155C)
IF Motor_Trip_Latched OR (Motor_Winding_Temp > 155.0) THEN
    Motor_Stop := TRUE;
ELSE
    // Normal operation control
    IF Start_Command THEN
        Motor_Stop := FALSE;
    ELSE
        Motor_Stop := TRUE;
    END_IF;
END_IF;

